import csv
import io


def parse_csv(raw_csv: str):
    width = 4
    reader = csv.reader(
        io.StringIO(raw_csv.removeprefix("\ufeff"), newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
    )

    def normalize(record):
        if len(record) > width:
            return record[:width - 1] + [",".join(record[width - 1:])]
        return record + [""] * (width - len(record))

    records = (record for record in reader if record)
    header = next(records, None)
    return {
        "columns": normalize(header) if header is not None else [],
        "rows": [normalize(record) for record in records],
    }
